// The entry files of a draft version, generated from its layout and its options.

import type { DraftOption, SharedValue } from '../../shared/index.ts';
import { pascalCase } from './names.ts';

const BANNER =
  '// Generated by kitvas from md/layout.md. Do not edit: change the layout and run "kitvas layout".';

const OPTIONS_BANNER =
  '// Generated by kitvas from src/json/options.json. Do not edit: change the options and run "kitvas layout".';

const SHARED_BANNER =
  '// Generated by kitvas from src/json/shared.json. Do not edit: change the shared values and run "kitvas layout".';

/**
 * `index.tsx`. With options or shared values, `Draft` takes them beside the state and hands all to
 * every section as a spread: a section that reads less keeps a smaller props type and still passes
 * the type check, which a named attribute would fail. The entry holds no state: the mount holds the
 * shared values. Without either, the file is the one an older version has.
 */
export function entryTsx(
  sections: { id: string }[],
  options: readonly DraftOption[] = [],
  shared: readonly SharedValue[] = [],
): string {
  const names = sections.map((section) => pascalCase(section.id));
  const withOptions = options.length > 0;
  const withShared = shared.length > 0;
  const spread = withOptions || withShared;
  const props = spread ? ' {...props}' : ' state={state}';
  const fields = [
    'state: string',
    ...(withOptions ? ['options: Options'] : []),
    ...(withShared ? ['shared: Shared', 'setShared: SetShared'] : []),
  ];
  return [
    BANNER,
    ...(withOptions ? ["import type { Options } from './options.ts';"] : []),
    ...(withShared ? ["import type { SetShared, Shared } from './shared.ts';"] : []),
    ...names.map((name) => `import { ${name} } from './sections/${name}.tsx';`),
    '',
    `export type DraftProps = { ${fields.join('; ')} };`,
    '',
    spread
      ? 'export function Draft(props: DraftProps) {'
      : 'export function Draft({ state }: DraftProps) {',
    '  return (',
    '    <>',
    ...names.map((name) => `      <${name}${props} />`),
    '    </>',
    '  );',
    '}',
    '',
  ].join('\n');
}

/** `options.ts`: the type of one choice, with the exact values of each option as unions. */
export function optionsTs(options: readonly DraftOption[]): string {
  const fields = options.map((option) => {
    const union = option.values.map((value) => JSON.stringify(value.id)).join(' | ');
    return `${JSON.stringify(option.id)}: ${union}`;
  });
  return [OPTIONS_BANNER, `export type Options = { ${fields.join('; ')} };`, ''].join('\n');
}

/**
 * `shared.ts`: the type of the shared values (a list is a union of its value ids, a text is
 * `string`) and the function that changes some of them.
 */
export function sharedTs(shared: readonly SharedValue[]): string {
  const fields = shared.map((value) => {
    const type =
      value.values === null
        ? 'string'
        : value.values.map((choice) => JSON.stringify(choice.id)).join(' | ');
    return `${JSON.stringify(value.id)}: ${type}`;
  });
  return [
    SHARED_BANNER,
    `export type Shared = { ${fields.join('; ')} };`,
    'export type SetShared = (change: Partial<Shared>) => void;',
    '',
  ].join('\n');
}

export function entryScss(sections: { id: string }[]): string {
  return [BANNER, ...sections.map((section) => `@use 'sections/${section.id}';`), ''].join('\n');
}
